<?php require 'config.php'; require 'lib.php'; need_login(); track_user(); csrf_check(); if($_SERVER['REQUEST_METHOD']==='POST'&&!is_admin()){ http_response_code(403); exit(t('Du har bara läsbehörighet.','You have read-only access.')); }
$TY=bmc_types();
function nconn0($old){ return ['snmp'=>snmp_param_build($_POST['s_ver']??'2',$_POST,$old['snmp']??'')]; }
function nconn($old){ return nw_conn_iv(nconn0($old)); }
function nrole(){ return 'bmc'; }
if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['a']??''; $hid=(int)($_POST['id']??$_POST['cid']??0); $pdo=db();
 if($a==='add'&&isset($TY[$_POST['type']??''])&&trim($_POST['host']??'')!==''){ $h=trim($_POST['host']);
  $pdo->prepare('INSERT INTO servers(name,host,nw_type,nw_role,nw_conn) VALUES(?,?,?,?,?)')->execute([trim($_POST['name']??'')?:$h,$h,$_POST['type'],nrole(),json_encode(nconn([]))]); $nid=$pdo->lastInsertId();
  $pdo->prepare("INSERT INTO server_checks(server_id,source,kind,target,label) VALUES(?,'tcp','ping','','Ping')")->execute([$nid]); applog('info','config','BMC device added: '.$h); $_SESSION['flash']=t('Enhet tillagd – första SNMP-avläsningen sker inom en minut (klicka på Testa nu för att se felmeddelanden direkt).','Device added – the first SNMP reading happens within a minute (click Test now to see any error right away).'); }
 if($a==='edit'&&isset($TY[$_POST['type']??''])&&trim($_POST['host']??'')!==''){ $q2=$pdo->prepare('SELECT nw_conn FROM servers WHERE id=?'); $q2->execute([$hid]); $old=json_decode((string)$q2->fetchColumn(),true)?:[]; $h=trim($_POST['host']);
  $pdo->prepare('UPDATE servers SET name=?,host=?,comment=?,nw_type=?,nw_role=?,nw_conn=?,nw_poll=NULL WHERE id=? AND nw_type IS NOT NULL')->execute([trim($_POST['name']??'')?:$h,$h,trim($_POST['comment']??''),$_POST['type'],nrole(),json_encode(nconn($old)),$hid]); }
 if($a==='test'){ $q=$pdo->prepare('SELECT * FROM servers WHERE id=? AND nw_type IS NOT NULL'); $q->execute([$hid]); if($s=$q->fetch()){ $r=poll_network($s); $_SESSION['flash']=$r['ok']?('✔ '.$s['name'].': CPU '.($r['data']['cpu']!==null?$r['data']['cpu'].'%':'–').', '.t('minne','memory').' '.($r['data']['mem']!==null?$r['data']['mem'].'%':'–').', '.count($r['ifs']).' interface'):('✖ '.$s['name'].': '.$r['error']); } }
 if($a==='toggle'){ $pdo->prepare('UPDATE servers SET enabled=1-enabled,nw_poll=NULL WHERE id=? AND nw_type IS NOT NULL')->execute([$hid]); $pdo->prepare('UPDATE server_checks SET last_check=NULL WHERE server_id=?')->execute([$hid]); }
 if($a==='toggle_dash') $pdo->prepare('UPDATE servers SET dash_hidden=1-dash_hidden WHERE id=? AND nw_type IS NOT NULL')->execute([$hid]);
 if($a==='del'){ applog('warning','config','BMC device deleted, id '.$hid); $q=$pdo->prepare('SELECT id FROM server_checks WHERE server_id=?'); $q->execute([$hid]); purge_targets([$hid],array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN))); $pdo->prepare('DELETE FROM servers WHERE id=? AND nw_type IS NOT NULL')->execute([$hid]); }
 header('Location: '.((($_POST['back']??'')==='detail'&&$a!=='del')?'netdev.php?id='.$hid:'bmc.php'));exit; }
$ed=null; $ec=[]; if(isset($_GET['edit'])&&is_admin()){ $q=db()->prepare('SELECT * FROM servers WHERE id=? AND nw_type IS NOT NULL'); $q->execute([(int)$_GET['edit']]); $ed=$q->fetch()?:null; $ec=$ed?(json_decode((string)$ed['nw_conn'],true)?:[]):[]; }
$sp=snmp_param_parse($ec['snmp']??'');
top('BMC'); flash(); ?>
<h2>BMC <small>iLO / iDRAC / IPMI</small></h2>
<?php if(is_admin()): ?><form method="post" class="card inline"><?= csrf_field() ?><input type="hidden" name="a" value="<?= $ed?'edit':'add' ?>"><?php if($ed) echo '<input type="hidden" name="id" value="'.$ed['id'].'">'; ?>
<select name="type" id="ntype"><?php foreach($TY as $k=>$n) echo '<option value="'.$k.'"'.(($ed['nw_type']??'idrac')===$k?' selected':'').'>'.h($n).'</option>'; ?></select>
<input type="hidden" name="role" value="bmc">
<input name="name" value="<?= h($ed['name']??'') ?>" placeholder="<?= t('Namn (valfritt)','Name (optional)') ?>"><input name="host" value="<?= h($ed['host']??'') ?>" placeholder="<?= 'IP/Hostname' ?>" required>
<?= nw_iv_input($ec) ?><input name="s_port" type="number" min="1" max="65535" style="width:110px" value="<?= h($sp["port"]??"") ?>" placeholder="<?= t("Port (standard 161)","Port (default 161)") ?>"> <select name="s_ver" class="sver"><option value="2"<?= $sp['ver']==='2'?' selected':'' ?>>SNMP v2c</option><option value="none"<?= $sp['ver']==='none'?' selected':'' ?>><?= t('Ingen SNMP (bara ping)','No SNMP (ping only)') ?></option><option value="3"<?= $sp['ver']==='3'?' selected':'' ?>>SNMP v3 (<?= t('standardinställningar','defaults') ?>)</option></select><input class="s2f" name="s_comm" value="<?= h($sp['comm']) ?>" placeholder="<?= 'Community' ?>"><?= snmp_v3_fields($sp) ?>

<?php if($ed): ?><label class="f" style="min-width:260px"><?= t('Kommentar','Comment') ?><textarea name="comment" rows="1" cols="30"><?= h($ed['comment']??'') ?></textarea></label><?php endif; ?>
<button class="btn"><?= $ed?t('Spara ändringar','Save changes'):t('Lägg till enhet','Add device') ?></button><?php if($ed) echo '<a class="btn danger" href="bmc.php">'.t('Avbryt','Cancel').'</a>'; ?></form><?php if(!$ed) echo nw_remember_js('bmc'); ?>
<?php endif; ?>
<?php $IFS=tc_ifs_by_server(); ?><table class="card"<?= tc_attr('bmc') ?>><tr><th data-k="name"><?= t('Namn','Name') ?></th><th data-k="type"><?= t('Typ','Type') ?></th><th data-k="model"><?= t('Modell','Model') ?></th><th data-k="addr"><?= t('Adress','Address') ?></th><th data-k="ping">Ping</th><th data-k="snmp">SNMP</th><th data-k="health"><?= t('Hälsa','Health') ?></th><th data-k="temp"><?= t('Temperatur','Temperature') ?></th><th data-k="watt"><?= t('Effekt','Power draw') ?></th><th data-k="pwr"><?= t('Fläktar / nätdelar','Fans / PSU') ?></th><th data-k="last"><?= t('Senaste kontroll','Last check') ?></th><?= tc_th('topif',t('Mest trafikerade interface','Top interface')) ?><?= tc_th('upt','Uptime') ?><?= tc_th('host','Hostname') ?><?= tc_th('ser',t('Serienummer','Serial number')) ?><?= tc_th('loc',t('Plats','Location')) ?><?= tc_th('cmt',t('Kommentar','Comment')) ?><?= tc_th('grp',t('Grupper','Groups')) ?><?= dg_ths() ?><th></th></tr>
<?php foreach(db()->query("SELECT s.*,TIMESTAMPDIFF(SECOND,nw_poll,NOW()) AS age,(SELECT last_status FROM server_checks c WHERE c.server_id=s.id AND c.kind='ping' LIMIT 1) ping,(SELECT COUNT(*) FROM net_if n WHERE n.server_id=s.id) nif,(SELECT COUNT(*) FROM net_if n WHERE n.server_id=s.id AND n.oper=1) nup FROM servers s WHERE s.nw_type IS NOT NULL AND s.nw_role='bmc' ORDER BY s.name") as $s): $d=json_decode((string)$s['nw_data'],true)?:[]; $en=(int)$s['enabled']===1; ?>
<tr class="<?= $en?'':'dim' ?>" data-href="netdev.php?id=<?= $s['id'] ?>"><td><b class="rn"><?= h($s['name']) ?></b><?= $en?'':' <small>('.t('inaktiverad','disabled').')</small>' ?><?= !empty($s['dash_hidden'])?' <small>('.t('dold på dash','hidden on dash').')</small>':'' ?><?= trim((string)$s['comment'])!==''?'<br><small class="mut">'.h($s['comment']).'</small>':'' ?></td><td><?= h(explode(' (',$TY[$s['nw_type']]??$s['nw_type'])[0]) ?></td><td class="det"><?= h(st_model($d['model']??'')?:'–') ?></td><td><?= h($s['host']) ?></td>
<td class="<?= $s['ping']==='up'?'okt':($s['ping']?'badt':'') ?>"><?= $s['ping']?:t('väntar','pending') ?></td><td class="det <?= $s['nw_status']==='up'?'okt':($s['nw_status']?'badt':'') ?>"><?= (json_decode((string)$s['nw_conn'],true)['snmp']??'')==='none'?'<span class="mut">'.t('av','off').'</span>':'' ?><?= $s['nw_status']?h($s['nw_status']).($s['nw_error']?' – '.h($s['nw_error']):''):t('väntar','pending') ?></td><td><?php $hl=$d['health']??[]; $hb=count(array_filter($hl,fn($x)=>$x['st']!=='ok')); echo $hl?'<span class="'.($hb?'badt':'okt').'">'.($hb?$hb.' '.t('avviker','not OK'):count($hl).' OK').'</span>':'–'; ?></td><td><?= isset($d['temp'])?round($d['temp']).' °C':'–' ?></td><td><?= isset($d['watts'])?round($d['watts']).' W':'–' ?></td><td><?php $fn=$d['fans']??[]; $ps=$d['psu']??[]; $bf=count(array_filter($fn,fn($x)=>empty($x['ok'])))+count(array_filter($ps,fn($x)=>empty($x['ok']))); echo ($fn||$ps)?'<span class="'.($bf?'badt':'okt').'">'.($bf?$bf.' '.t('avviker','not OK'):'OK').'</span>':'–'; ?></td><td><?= $s['age']===null?'–':($s['age']<60?$s['age'].' s':floor($s['age']/60).' min') ?></td>
<?php echo tc_topif($IFS[$s['id']]??[]),tc_td(!empty($d['uptime'])?tc_upt($d['uptime']):null,(int)($d['uptime']??0)),tc_td($d['hostname']??null),tc_td($d['serial']??null),tc_td($d['location']??null),tc_td($s['comment']??null); ?>
<?= dg_td($s['id']) ?><?= dg_tds($s['id']) ?><td class="inline"><?php if(is_admin()): ?><a class="btn sm" href="bmc.php?edit=<?= $s['id'] ?>"><?= t('Ändra','Edit') ?></a><?= fbtn('toggle',$s['id'],$en?t('Inaktivera','Disable'):t('Aktivera','Enable'),$en?'warn':'go') ?><?= fbtn('del',$s['id'],t('Ta bort','Delete'),'danger',t('Ta bort enheten och all dess data?','Delete the device and all its data?')) ?><?php endif; ?></td></tr>
<?php endforeach; ?></table>
<?php bottom();
